package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"
)

type PartRec struct {
	LbPart   string // PIC X(8) @0 len=8
	LbRegion string // PIC X(3) @8 len=3
	LbSerial int64  // PIC 9(4) @11 len=4
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N"
var WsLabel string = "                    " // 20 spaces
var WsACount int64 = 0
var WsTotalA int64 = 0
var WsCount int64 = 0

// Input handling
var inputLines []string
var inputIndex int
var curRec PartRec

func truncateDigits(v int64, digits int) int64 {
	mod := int64(1)
	for i := 0; i < digits; i++ {
		mod *= 10
	}
	v = v % mod
	if v < 0 {
		v += mod
	}
	return v
}

func formatNumeric(v int64, digits int) string {
	v = truncateDigits(v, digits)
	fmtStr := fmt.Sprintf("%%0%dd", digits)
	return fmt.Sprintf(fmtStr, v)
}

func padRight(s string, n int) string {
	if len(s) >= n {
		return s[:n]
	}
	return s + strings.Repeat(" ", n-len(s))
}

func delimitedBySpace(s string) string {
	idx := strings.Index(s, " ")
	if idx == -1 {
		return s
	}
	return s[:idx]
}

func delimitedBySizeAlnum(s string) string {
	return s
}

func delimitedBySizeNumeric(v int64, digits int) string {
	return formatNumeric(v, digits)
}

// paragraphs

func READ_PARA() {
	if inputIndex >= len(inputLines) {
		WsEofFlag = "Y"
		return
	}
	line := inputLines[inputIndex]
	inputIndex++
	// pad/truncate to 15
	if len(line) < 15 {
		line = line + strings.Repeat(" ", 15-len(line))
	} else if len(line) > 15 {
		line = line[:15]
	}
	lbPart := line[0:8]
	lbRegion := line[8:11]
	lbSerialRaw := line[11:15]
	var lbSerial int64 = 0
	// parse digits only, ignoring non-digits? COBOL numeric field digits.
	// Input digits only.
	for _, ch := range lbSerialRaw {
		if ch >= '0' && ch <= '9' {
			lbSerial = lbSerial*10 + int64(ch-'0')
		}
	}
	// Keep as stored value truncated to 4 digits? COBOL MOVE to PIC 9(4) would keep low-order digits.
	lbSerial = truncateDigits(lbSerial, 4)
	curRec.LbPart = lbPart
	curRec.LbRegion = lbRegion
	curRec.LbSerial = lbSerial
}

func PROCESS_PARA() {
	// MOVE SPACES TO WS-LABEL
	WsLabel = strings.Repeat(" ", 20)
	// MOVE 0 TO WS-A-COUNT
	WsACount = 0
	// INSPECT LB-PART TALLYING WS-A-COUNT FOR ALL "A"
	WsACount = int64(strings.Count(curRec.LbPart, "A"))
	WsACount = truncateDigits(WsACount, 2)

	// STRING ... INTO WS-LABEL
	partRegion := delimitedBySpace(curRec.LbRegion)
	partDash1 := delimitedBySizeAlnum("-")
	partPart := delimitedBySpace(curRec.LbPart)
	partDash2 := delimitedBySizeAlnum("-")
	partSerial := delimitedBySizeNumeric(curRec.LbSerial, 4)

	concat := partRegion + partDash1 + partPart + partDash2 + partSerial
	// STRING does not clear target, but we blanked; truncate or pad
	if len(concat) > 20 {
		WsLabel = concat[:20]
	} else {
		WsLabel = concat + strings.Repeat(" ", 20-len(concat))
	}

	// INSPECT WS-LABEL REPLACING ALL "0" BY "O"
	WsLabel = strings.ReplaceAll(WsLabel, "0", "O")

	// ADD WS-A-COUNT TO WS-TOTAL-A
	WsTotalA = truncateDigits(WsTotalA+WsACount, 3)
	// ADD 1 TO WS-COUNT
	WsCount = truncateDigits(WsCount+1, 3)

	// DISPLAY WS-LABEL " A=" WS-A-COUNT
	// WS-LABEL PIC X(20) prints exactly 20 chars
	// literal " A=" then WS-A-COUNT PIC 99 zero-padded 2
	out := WsLabel + " A=" + formatNumeric(WsACount, 2) + "\n"
	os.Stdout.WriteString(out)

	// PERFORM READ-PARA
	READ_PARA()
}

func SUMMARY_PARA() {
	// DISPLAY "LABELS: " WS-COUNT " A-TOTAL: " WS-TOTAL-A
	out := "LABELS: " + formatNumeric(WsCount, 3) + " A-TOTAL: " + formatNumeric(WsTotalA, 3) + "\n"
	os.Stdout.WriteString(out)
}

func MAIN_PARA() {
	// OPEN INPUT PART-FILE
	// load file input.dat line sequential
	f, err := os.Open("input.dat")
	if err != nil {
		// if file not found, treat as empty (COBOL would error, but for translation we handle)
		inputLines = []string{}
	} else {
		scanner := bufio.NewScanner(f)
		// allow long lines
		buf := make([]byte, 0, 64*1024)
		scanner.Buffer(buf, 1024*1024)
		for scanner.Scan() {
			line := scanner.Text()
			// Remove trailing \r if present (Scanner already strips \n, but \r remains for CRLF)
			line = strings.TrimSuffix(line, "\r")
			inputLines = append(inputLines, line)
		}
		f.Close()
	}
	inputIndex = 0
	PERFORM_READ_PARA := READ_PARA
	_ = PERFORM_READ_PARA
	READ_PARA()
	for !(WsEofFlag == "Y") {
		PROCESS_PARA()
	}
	// CLOSE PART-FILE (already closed)
	SUMMARY_PARA()
}

func main() {
	MAIN_PARA()
}
